  .cabecRes{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:16px}
  .cabecRes .rotulo2{font-size:.74rem;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
  .estatisticas{display:flex;gap:10px;flex-wrap:wrap}
  .stat-item{display:flex;align-items:center;gap:7px;font-size:.74rem;color:var(--muted)}
  .stat-item .pontinho{width:8px;height:8px;border-radius:50%;background:var(--glow)}
  .outro{
    width:100%;appearance:none;background:transparent;
    border:1px solid var(--limite-borda);border-radius:var(--rn);
    color:var(--txt);font:inherit;padding:14px 14px;
    resize:vertical;overflow:hidden;line-height:1.5;min-height:130px;
    transition:border-color .25s,box-shadow .25s;
  }
  .outro:focus{outline:none;border-color:var(--ring);box-shadow:0 0 0 4px rgba(162,155,255,.16)}
  .outro::placeholder{color:var(--muted)}
  .area-copiar{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:14px}

  /* Notificações */
  .bar-notif{position:fixed;top:14px;right:14px;z-index:9999;flex-direction:column;gap:8px;width:min(360px,92vw);pointer-events:none;overflow:hidden}
  .notif{
    pointer-events:auto;max-height:270px;overflow:hidden;
    background:rgba(17,24,40,.93);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
    border:1px solid rgba(123,95,255,.3);border-left:4px solid #3fb950;
    border-radius:13px;padding:12px 15px;color:#e6eaf1;
    font:inherit;display:flex;align-items:center;gap:11px;
    box-shadow:0 10px 26px rgba(0,0,0,.55);
    animation:entrar .3s cubic-bezier(.2,0,.2,1) forwards;
  }
  .notif.alerta{border-left-color:#ffb84c}
  .notif.erro{border-left-color:#f0a500}
  .notif strong{font-weight:600}
  .notif .marca{font-size:1rem;line-height:1}
  .notif.saia{animation:sair .26s ease forwards}
  @keyframes entrar{from{transform:translateY(32px) scale(.94);opacity:0} to{transform:translateY(0) scale(1);opacity:1}}
  @keyframes sair{from{transform:translateY(0) scale(1);opacity:1} to{transform:translateY(42px) scale(.88);opacity:0}}

  footer{margin-top:8px;color:var(--muted);font-size:.7rem;text-align:center}
</style>
</head>
<body>

<!-- ═════════ HERO ═════════ -->
<section class="hero">
  <div class="row-titulo">
    <div>
      <h1>Super Retirador de Texto Paps</h1>
      <p class="tagline">
        Seu texto, sem bagunça: apague palavras, pontuações e símbolos numa única ação com apenas um clique.
