        <line x1="12" y1="1" x2="12" y2="3"/>
        <line x1="12" y1="21" x2="12" y2="23"/>
        <line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/>
        <line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/>
        <line x1="1" y1="12" x2="3" y2="12"/>
        <line x1="21" y1="12" x2="23" y2="12"/>
        <line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/>
        <line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>
      </svg>
    </button>
  </div>
</section>

<!-- ═════════ FORMULÁRIO ═════════ -->
<main class="app">
  <section class="sec-form">
    <div class="caixa-entrada">
      <label for="txtEntrada" class="rotulo">Seu texto original ⬆️</label>
      <textarea id="txtEntrada" class="" placeholder="Cole aqui todo o seu texto, com tudo o que estiver... (mantém quebras de linha)"><span class="hint-abre">Ou cole de fora — pode ter parágrafos, emojis e o que for preciso 😉</span></textarea>
    </div>

    <div class="grid-passo">
      <!-- Passo 1 -->
      <div class="passo" data-id="1">
        <div class="numero-passo">1</div>
        <span class="nome">Passo 1 · Palavras soltas</span>
        <span class="extra">✂️ Palavra ou chamada repetida</span>
        <span class="exemp">Ex.: digite "super"</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false" autofocus>
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 2 -->
      <div class="passo" data-id="2">
        <div class="numero-passo">2</div>
        <span class="nome">Passo 2 · Pontuação pesada</span>
        <span class="extra">⚡ Pontos, interrogações e afins</span>
        <span class="exemp">Ex.: "! ? ."</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
