      <!-- Passo 3 -->
      <div class="passo" data-id="3">
        <div class="numero-passo">3</div>
        <span class="nome">Passo 3 · Símbolos conhecidos</span>
        <span class="extra">🧾 Símbolos que poluem o texto</span>
        <span class="exemp">Ex.: "@ # $ %"</span>
        <span class="badge-pn"></span>
        <input class="in-step" type="text" autocomplete="off" spellcheck="false">
        <div class="status-linha esperando">— aguardando padrão</div>
      </div>

      <!-- Passo 4 -->
      <div class="passo" data-id="4">
        <div class="numero-passo">4</div>
        <span class="nome">Passo 4 · Outros caracteres</span>
        <span class="extra">🪝 Asteriscos, chaves, barras e mais</span>
        <span class="exemp">Ex.: "* + - _ { } | <<>>"</span>
