<footer>© 2026 Super Retirador de Texto Paps · Feito com carinho e código limpo 💜</footer>

<script>
(function(){ "use strict";

  /* ═════════ CONFIGURAÇÃO ═════════ */
  const PASSOS = [
    { id:1, nome:'Passo 1', extra:'✂️ Palavra ou chamada repetida',   exemp:'Ex.: digite "super"' },
    { id:2, nome:'Passo 2', extra:'⚡ Pontuação pesada',              exemp:'Ex.: "! ? ." ' },
    { id:3, nome:'Passo 3', extra:'🧾 Símbolos conhecidos',           exemp:'Ex.: "@ # $ %"' },
    { id:4, nome:'Passo 4', extra:'🪝 Outros caracteres',             exemp:'Ex.: "* + - _ { } | <<>>"' },
    { id:5, nome:'Passo 5', extra:'👹 Emoji e códigos',                exemp:'Qualquer coisa estranha' },
  ];
  const TAMPO_TEMA   = 'pps_tema';
  const BUSCA_NOTIF  = document.querySelector('.bar-notif');

  /* ═════════ UTILITÁRIOS ═════════ */
  function escHTML2(t){
    return String(t != null ? t : '')
      .replace(/[&<>"']/g, function(ch){
        return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'": '&#39;' }[ch];
      });
  }
  function escaparPadrao(s){
    // transforma símbolos em sequências seguras para regex (evita erros de sintaxe)
    return s.replace(/[.*+?^${}()|[\]\\]/g, function(m){ return '\\' + m; });
  }
  function contarPadrao(valorCompleto, padrao){
    try{ return (valorCompleto.match(new RegExp(escaparPadrao(padrao),'g')) || []).length; }
    catch(e){ return 0; }
  }

  /* ═════════ TEMA CLARO / ESCURO ═════════ */
  function carregarTema(){
    const pref = localStorage.getItem(TAMPO_TEMA)||'dark';
    document.body.classList.toggle('light-mode', pref==='light');
    localStorage.setItem(TAMPO_TEMA, pref);
    marcarIcons();
  }
  function marcarIcons(){
    const luna = document.querySelector('.icone-luna');
    const sol  = document.querySelector('.icone-sol');
    if(document.body.classList.contains('light-mode')){
      luna.classList.add('ativo');luna.classList.remove('base');
      sol.classList.add('base');sol.classList.remove('ativo');
    }else{
      luna.classList.remove('ativo');luna.classList.add('base');
      sol.classList.add('ativo');sol.classList.remove('base');
    }
  }
  const BtnTema = document.querySelector('.trocar-tema');
  BtnTema.addEventListener('click', function(){
    const prox = document.body.classList.contains('light-mode') ? 'dark' : 'light';
    document.body.classList.toggle('light-mode', prox==='light');
    localStorage.setItem(TAMPO_TEMA, prox);
    marcarIcons();
  });
  carregarTema();

  /* ═════════ ESTADO GERAL ═════════ */
  let rodando = false;

  function pararAnimacao(btn){
    btn.classList.remove('ativando');
    const sp = btn.querySelector('.spi');
    if(sp) sp.remove();
  }

  /* ═════════ NOTIFICAÇÕES ═════════ */
  const MARCAS = { info:'', sucesso:'sucesso', alerta:'', erro:'erro' };
  function avisar(html, tipo){
    tipo = (tipo||'info').toLowerCase();
    const el = document.createElement('div');
    el.className = 'notif ' + (MARCAS[tipo]||'');
    const emoticones = { info:'ℹ️', sucesso:'✅', alerta:'⚠️', erro:'❌' };
    el.innerHTML = '<span class="marca">' + emoticones[tipo||'info'] + '</span>' + escHTML2(html);
    if(!BUSCA_NOTIF) return;
    BUSCA_NOTIF.style.pointerEvents = 'none';
    if(BUSCA_NOTIF.childElementCount > 3) BUSCA_NOTIF.removeChild(BUSCA_NOTIF.firstChild); // mantém só as 3 últimas
    BUSCA_NOTIF.style.pointerEvents = 'auto';
    BUSCA_NOTIF.appendChild(el);
    el._fim = setTimeout(function(){
      el.classList.add('saia');
      el.addEventListener('transitionend', function(){ el.remove(); }, { once:true });
    }, 3600);
  }

  /* ═════════ PROCESSAMENTO PRINCIPAL ═════════ */
  function dispararLimpeza(){
    rodando = true;
    document.getElementById('btnLimpar').disabled  = true;
    document.getElementById('btnLimpar').classList.add('ativando');
    document.getElementById('btnZERAR').disabled  = true;
    document.getElementById('btnCopiar').disabled = true;
    document.getElementById('btnLimpar').setAttribute('aria-busy','true');

    const inicio = performance.now();
    let conteudo = document.getElementById('txtEntrada').value;
    const log = [];

    try {
      for(let i=0; i<PASSOS.length; i++){
        const cartao = document.querySelectorAll('.passo')[i];
        const padrao = String(document.querySelectorAll('.in-step')[i].value || '')
                      .trimStart().trimEnd();

        if(padrao.length <= 0){
          atualizaCartao(cartao, '-', 0);
          continue;
        }

        const antes = conteudo;
        const reg   = new RegExp(escaparPadrao(padrao), 'g');
        const encontrados = antes.match(reg)?.length || 0;
        conteudo = conteudo.replace(reg, '');

        const detalhes = { indice:i+1, padrao:padrao, removidos:encontrados };
        log.push(detalhes);
        atualizaCartao(cartao, padrao, encontrados);
        atualizarBadges();

        if(i < PASSOS.length - 1) {
          // pequena pausa entre etapas para não travar a UI
          await new Promise(function(r){ setTimeout(r, 150); });
        }
      }

      const total = log.reduce(function(a,x){ return a+x.removidos; }, 0);

      document.getElementById('resTexto').value = conteudo;
      document.getElementById('resTexto').focus();
      abrirPlacar(total, ((performance.now()-inicio)/1000).toFixed(1));
      avisar('✅ Missão cumprida! Foram retiradas ' + total.toLocaleString() + ' ocorrência(s) em ' + duração + 's. Veja o resultado abaixo 👇', 'sucesso');
      setTimeout(function(){ document.getElementById('btnCopiar').focus(); }, 360);

    }catch(err){
      rodando = false;
      pararAnimacao(document.getElementById('btnLimpar'));
      pararAnimacao(document.getElementById('btnZERAR'));
      pararAnimacao(document.getElementById('btnCopiar'));
      document.getElementById('btnZERAR').disabled = false;
      document.getElementById('btnCopiar').disabled = false;
      document.getElementById('btnLimpar').setAttribute('aria-busy','false');
      avisar('⚠️ Não conseguiu remover tudo. Confira os padrões digitados nas caixinhas e tente novamente.', 'erro');
    }
  }

  function atualizaCartao(cartao, padrao, achados){
    const linha = cartao.querySelector('.status-linha');
    if(!linha) return;
    const texto = achados > 0
      ? '✅ ' + achados.toLocaleString() + '× removidos "' + escHTML2(padrao) + '"'
      : '— nada encontrado ainda';
    linha.className = 'status-linha ' + (achados>0 ? 'retirado' : 'esperando');
    linha.textContent = texto;
    cartao.style.borderColor = achados > 0 ? '#3fb950' : 'var(--limite-borda)';
  }

  function atualizarBadges(){
    document.querySelectorAll('.in-step').forEach(function(inp){
      const cheios   = inp.value.length > 0;
      const visivel  = inp.value.trimStart().trimEnd();
      const achados  = contarPadrao(inp.value, visivel);

      inp.classList.toggle('has-badge', cheios);
      inp.classList.toggle('no-badge', !cheios);
      const painel = inp.querySelector('.badge-pn');
      if(!painel) return;

      if(!cheios){
        painel.style.opacity = '0'; painel.style.transform = 'scale(.5)';
        painel.style.pointerEvents = 'none'; return;
      }
      painel.style.opacity = '1';
      painel.style.transform = 'scale(1)';
      painel.style.pointerEvents = 'auto';
      painel.style.color = achados >= 10 ? '#f0a500' : (achados >= 1 ? '#6fcf6f' : '#a29bfe');
      painel.textContent = String(achados);
    });
  }

  function abrirPlacar(total, dur){
    const cab = document.querySelector('.cabecRes');
    if(!cab) return;
    const lista = cab.querySelector('.estatisticas');
    if(!lista){
      lista = document.createElement('div');
      lista.className = 'estatisticas';
      cab.appendChild(lista);
    }
    const itens = document.createElement('div');
    itens.className = 'stat-item';
    itens.innerHTML = '<span class="pontinho"></span><span>' + total.toLocaleString() + ' ajustes aplicados</span>';
    lista.appendChild(itens);

    if(dur && parseFloat(dur) > 0){
      const it2 = document.createElement('span');
      it2.className = 'stat-item';
      it2.innerHTML = '<span class="pontinho" style="background:#7b5ffa"></span><span>Pronto em ' + dur + 's</span>';
      lista.appendChild(it2);
    }
  }

  /* ═════════ BOTÕES ═════════ */
  const btnLimpar = document.getElementById('btnLimpar');
  const btnZerar  = document.getElementById('btnZERAR');
  const btnCopiar = document.getElementById('btnCopiar');

  btnLimpar.addEventListener('click', dispararLimpeza);

  btnZerar.addEventListener('click', function(){
    document.getElementById('resTexto').value   = '';
    document.getElementById('txtEntrada').value = '';
    document.querySelectorAll('.in-step').forEach(function(i){ i.value = ''; });
    avisar('⚡ Tudo zerado! Novos texto e padrões prontos para uso 😉', 'info');
  });

  btnCopiar.addEventListener('click', async function(){
    const texto = document.getElementById('resTexto').value.trim();
    if(!texto){
      avisar('⚠️ Ainda não há texto processado — rode o processo antes de copiar 😉', 'erro');
      return;
    }
    try{
      await navigator.clipboard.writeText(texto);
      avisar('✅ Copiado para a Área de Transferência! 🎉 Agora é só colar onde quiser!', 'sucesso');
    }catch(e){
      avisar('⚠️ Não foi possível copiar de forma automática — selecione o texto do resultado e use Ctrl+C manualmente 😉', 'erro');
    }
  });

  /* ═════════ INICIALIZAÇÃO VISUAL DOS CARTÕES ═════════ */
  PASSOS.forEach(function(p, idx){
    const cartao = document.querySelectorAll('.passo')[idx];
    const nome   = cartao.querySelector('.nome');
    const extra  = cartao.querySelector('.extra');
    if(!extra){
      extra = document.createElement('span');
      extra.className = 'extra';
      extra.textContent = p.extra;
      nome.appendChild(extra);
    }
    const status = document.createElement('div');
    status.className = 'status-linha esperando';
    status.textContent = '— aguardando padrão';
    extra.appendChild(status);
  });

  /* Pequeno foco inicial (somente quando já houver texto) */
  /* Nada adicional necessário — tudo explicado pelos placeholders e dicas */

})();
</script>
</body>
</html>
