double FiboPts(double base, double top, double pct){ return RoundDP(base+(top-base)*pct, InpFiboPrec); }

// ---------------------------------------------------------------------------
// ATR exponencial simples (em pontos do grafico)
// ---------------------------------------------------------------------------
double CalcATR(int per, int ini=0){
   double k=(per>0)?(1.0-1.0/per):0.0;
   double w=0.0, s=0.0;
   int lim=MathMin(ini+per, g_CntBars-0);
   for(int i=ini;i<lim;i++){
      double dd=(i==ini)?0.0:MathAbs(g_Buffer[i]-g_Buffer[i-1]);
      w = k*(dd-w)+w; s += w;
   }
   int nUsed=lim-ini;
   return nUsed>0 ? s/nUsed : 0.0;
}

