// -------- 1) VIRADAS (fundamentais p/ Ordem Bloco) ---------------
void DetectarViradas(){
   if(g_CntBars<10) return;
   double corpMed=0.0; int cc=0;
   for(int i=4;i<MathMin(g_CntBars-3,14);i++){
      double mn=INF, mx=-INF;
      for(int k=i-5;k<=i+5;k++){ if(k<0||k>=g_CntBars)continue;
         double l=(g_LBuf[k]<0)?0:g_LBuf[k]; double h=(g_HBuf[k]<0)?0:g_HBuf[k];
         mx=MathMax(mx,h); mn=MathMin(mn,l);}
      cc++; corpMed+=(h-mn);
   }
   if(cc==0) return;
   double th = corpMed/cc * InpThrBody; // limiar de relevância da virada
   list<Extremo> alts, baixas; alts.clear(); baixas.clear();
   bool alto=false;
   double va=0, ib=-1, ia=-1;
   const double* B=(double*)g_Buffer;
   for(int i=1;i<g_CntBars-1;i++){
      if(MathIsNaN(B[i])) continue;
      int s=MathMax(0,i-5), e=MathMin(g_CntBars-1,i+5);
      double mx=-1e30, mn=1e30;
      for(int k=s;k<=e;k++){ if(k>=g_CntBars)continue;
         double l=(g_LBuf[k]<0)?0:g_LBuf[k]; double h=(g_HBuf[k]<0)?0:g_HBuf[k];
         mx=MathMax(mx,h); mn=MathMin(mn,l); }
      bool hi=(B[i]==mx && B[i]>=B[i-1] && B[i]>=B[i+1]);
      bool lo=(B[i]==mn && B[i]<=B[i-1] && B[i]<=B[i+1]);
      if(!(hi||lo)) continue;
      double d=MathMin(MathAbs(B[i]-B[i-1]),MathAbs(B[i]-B[i+1]));
      if(d<0.55*th) continue;

      if(hi){
         if(alto){
            if(va<B[i]-th*0.9 && (i-ia)<=InpSwingRadius && ia>=0){
               alts.push_back((Extremo){B[i],i,+1});
               if((int)alts.size()>InpObMaxTotal+2)
                  alts.erase(alts.begin(),alts.begin()+InpObMaxTotal+2);
            }
         }
         alto=false; ia=i; va=B[i];
      }else{ // fundo
         if(alto){
            if(ib<0 || (B[i]<va-th*0.9 && (i-ib)<=InpSwingRadius && ib>=0)){
               baixas.push_back((Extremo){B[i],i,-1});
               if((int)baixas.size()>InpObMaxTotal*2+4)
                  baixas.erase(baixas.begin(),baixas.begin()+InpObMaxTotal*2+4);
            }
         }else{
            if((int)baixas.size()<InpObMaxTotal){
               baixas.push_back((Extremo){B[i],i,-1});
            }else if(i-ib<=InpSwingRadius*1.5 && B[i]<va-th*0.9 && ib>=0){
               baixas.push_back((Extremo){B[i],i,-1});
            }
         }
         alto=true; ib=i; va=B[i];
      }
   }
}

// -------- 2) ORDENS BLOCO -----------------------------------------
void FormarOBD(){
   vector<ZonaOB> comps; comps.reserve(40);
   vector<bool> us((int)max(g_Altas.size(),g_Baixas.size())+2,false);

   // Compra: fundo -> topo (valor sobe)
   int a0=-1;
   for(int bi=0;bi<(int)baixas.size()-1;bi++){
      if(a0<0 || baixas[bi].barra<a0) continue;
      double lo=baixas[bi].nivel;
      int sj=bi+1;
      for(int ak=sj;ak<(int)alts.size();ak++){
         if(us[ak]) continue;
         if(alts[ak].barra-bi>InpObWindow) break;
         if(alts[ak].nivel>lo+InpObDiffMin && alts[ak].barra>bi){
            us[ak]=true; us[(int)baixas[bi].barra]=true;
            comps.push_back({lo, alts[ak].nivel,+1});
            if((int)comps.size()>InpObMaxTotal) comps.resize(InpObMaxTotal);
            break;
         }
      }
   }
   // Venda: topo -> fundo (valor cai)
   vector<bool> ua((int)max(g_Altas.size(),g_Baixas.size())+2,false);
   int h0=-1;
   for(int ai=0;ai<(int)alts.size()-1;ai++){
      if(h0<0 || alts[ai].barra<a0) continue;
      double hi=alts[ai].nivel;
      int sj=ai+1;
      for(int bl=sj;bl<(int)baixas.size();bl++){
         if(ua[bl]) continue;
         if(baixas[bl].barra-ai>InpObWindow) break;
         if(baixas[bl].nivel<hi-InpObDiffMin && baixas[bl].barra>ai){
            ua[bl]=true; us[(int)alts[ai].barra]=true;
            comps.push_back({baixas[bl].nivel, hi,-1});
            if((int)comps.size()>InpObMaxTotal) comps.resize(InpObMaxTotal);
            break;
         }
      }
   }
   DedupZonas(comps);
   g_Zonas.assign(comps.begin(),comps.end());
}
void DedupZonas(const vector<ZonaOB>& z){
   if(z.size()<2) return;
   sort(z.begin(),z.end(),[](const ZonaOB& a,const ZonaOB& b){return a.base<b.base;});
   vector<ZonaOB>m;
   for(int i=0;i<z.size();i++){
      if(m.empty()){ m.push_back(z[i]); continue; }
      double d=MathAbs(m.back().base-z[i].base);
      if(d>1.5*InpObDiffMin || z[i].topo-m.back().topo>InpObDiffMin*2){ m.push_back(z[i]); }
   }
   g_Zonas.assign(m.begin(),m.end());
}

// -------- 3) FGV (Fair Value Gap) ---------------------------------
void DetectFGVs(){
   g_FGVs.size(0);
   if(g_CntBars<5) return;
   for(int i=1;i<g_CntBars-1;i++){
      double d=MathAbs(g_Buffer[i]-g_Buffer[i-1]);
      if(d<=0.5*CalcATR(11)) continue;
      if(d>InpGapMult*CalcATR(11)){
         bool cheio=false;
         for(int k=i+1;k<i+14;k++){ if(k>=g_CntBars)break;
            double db=MathAbs(g_Buffer[k]-g_Buffer[i-1]); double dc=MathAbs(g_Buffer[k]-g_Buffer[i]);
            if(MathMin(db,dc)<0.45*d) cheio=true; }
         FGVd fv={(g_Buffer[i-1]+g_Buffer[i])/2, i,
                  (g_Buffer[i]>g_Buffer[i-1]?1:-1), cheio};
         g_FGVs.push_back(fv);
      }
   }
   if((int)g_FGVs.size()>30) g_FGVs.resize(30);
}

