void ObterRange(vector<double>& pts){
   vector<double>c;
   // tenta usar o ultimo swing valido (alto -> baixo)
   if(g_Baixas.size()>=2 && g_Altas.size()>=2){
      int bestA=-1, bestB=-1;
      for(int i=(int)g_Baixas.size()-1;i>=0;i--){
         if(g_Baixas[i].barra>bestB) bestB=(int)g_Baixas[i].barra;
         if(g_Altas[i].barra>bestA && g_Altas[i].barra-(int)g_Baixas[i].barra>4) bestA=(int)g_Altas[i].barra;
      }
      if(bestA>=0 && bestB>=0){
         double r=g_Buffer[bestA]-g_Buffer[bestB];
         if(r>InpRangeMin*1.3){ pts.push_back(g_Buffer[bestB]); pts.push_back(g_Buffer[bestA]); return; }
      }
   }
   // fallback: min/max dos ultimos fechamentos
   int s=MathMax(0,g_CntBars-120), e=g_CntBars-1;
   double mn=INF, mx=-INF;
   for(int i=s;i<=e;i++){
      double l=(g_LBuf[i]<0)?0:g_LBuf[i]; double h=(g_HBuf[i]<0)?0:g_HBuf[i];
      mn=MathMin(mn,l); mx=MathMax(mx,h); }
   double rr=mx-mn;
   if(rr>InpRangeMin*1.3){ pts.push_back(mn); pts.push_back(mx); return; }
   // fallback fraco (ruído aceito apenas se não houver outra opcao)
   pts.push_back(g_Buffer[g_CntBars-1]-RoundDP(g_Buffer[g_CntBars-1]*0.382,InpFiboPrec));
   pts.push_back(g_Buffer[g_CntBars-1]+RoundDP(g_Buffer[g_CntBars-1]*0.618,InpFiboPrec));
}
void GerarFibos(vector<double>& pts){
   double base=pts[0], top=pts[1];
   static const double fibos[] = {0.0, 0.236, InpFibo1, InpFibo2, InpFibo3, 0.764, 1.0};
   for(double p: fibos){
      if(MathAbs(p-1.0)<0.001) continue;
      pts.push_back(FiboPts(base,top,p));
   }
   if(!InpExtenders) return;
   pts.push_back(FiboPts(base,top,0.764));
   pts.push_back(FiboPts(base,top,1.0));
}
