                case4:"61.8%"; case5:"76.4%"; case6:"100%"; default:"?";}
   return string();
}
double NivelMaisProximo(const vector<double>& fibos, double p){
   double d=1e30; int best=0;
   for(int i=0;i<fibos.size();i++){
      double dv=math_abs(fibos[i]-p); // math_abs nao existe -> substituir
      if(MathAbs(dv-d)<0.001){ best=i; d=dv; }else if(dv<d){ best=i; d=dv; }
   }
