double FiboPts(double base, double top, double pct){ return RoundDP(base+(top-base)*pct,3); }

double CalcATR(int per, int ini=0){
   double k=(per>0)?(1.0-1.0/per):0.0, w=0.0, s=0.0;
   int lim=MathMin(ini+per, g_CntBars-0);
   for(int i=ini;i<lim;i++){
      double dd=(i==ini)?0.0:MathAbs(g_Buffer[i]-g_Buffer[i-1]);
      w = k*(dd-w)+w; s+=w; }
   int nu=lim-ini; return nu>0? s/nu:0.0;
}

double CalcEMA(const double* src, int per, int ini=0){
   double k=(per>0)?(1.0-1.0/per):0.0, e=0.0;
   for(int i=ini;i<MathMin(ini+per,g_CntBars);i++){
      if(MathIsNaN(src[i])) continue;
      e = k*(src[i]-e)+e; }
   return e;
}

int DirecaoTendencia(){
