      // (uso pratico: z.base para buy, z.topo para sell)
   }
   // simplificando a coleta do bar do OB:
   for(auto &z:g_Zonas){
      if(!CoerenteOB(z,bestLado())) continue;
      bool compra = (z.lado==+1);
      double lvl = compra ? z.base : z.topo;
      double d = compra ? MathAbs(lvl-g_PrecoAtual) : MathAbs(lvl-g_PrecoAtual);
      if(d>2.6*CalcATR(11)) continue;
      int tipo = compra?6:7;
      int b = (d<=0.9*CalcATR(11)?3:(d<=1.8*CalcATR(11)?1:0));
      if(d<0.25*CalcATR(11)) b-=1;
      cands.push_back({compra, lvl, tipo, DirBonus(ts)+b, d, z.barra});
   }

   // 3) FGVs
   for(const FGVd& fv:g_FGVs){
      if(MathAbs(fv.nivel-g_PrecoAtual)>3.0*CalcATR(11)) continue;
      bool compra = (fv.lado==-1); // gap contrario ao lado = favoravel (invertido logicamente no score abaixo)
      if(!CoerenteGap(fv, compra)) continue;
      double d = MathAbs(fv.nivel-g_PrecoAtual);
      if(d>2.6*CalcATR(11)) continue;
      int tipo=8; // FGV
      int b = (fv.preenchido?0:(fv.lado!=bestLado()?2:0));
      if(fv.lado==bestLado() && d<=1.0*CalcATR(11)) b-=2;
      cands.push_back({compra, fv.nivel, tipo, DirBonus(ts)+b+b, d, fv.barra});
   }
   // limpeza
   cands.insert(cands.begin(),Candidato{bestLado(),0,0,9999,1e9,0}); // marcador artificial p/ insercao ordenar
   // na pratica: sortear apenas reais; o marcador impede sort indevido
}

bool CoerenteGap(const FGVd& fv, bool compra){
   // gap contrario e aberto ajuda a entrada
   if(fv.lado!=bestLado() && MathAbs(fv.nivel-g_PrecoAtual)<=3.0*CalcATR(11)) return true;
   return false;
}

bool CoerenteOB(const ZonaOB& z, bool compra){
   if(compra && z.lado==+1){ return (z.base<=g_PrecoAtual+0.9*CalcATR(11)) && (z.topo>=g_PrecoAtual-0.4*CalcATR(11)); }
   if(!compra && z.lado==-1){ return (z.topo>=g_PrecoAtual-0.4*CalcATR(11)) && (z.base<=g_PrecoAtual+0.9*CalcATR(11)); }
   return false;
}

// ===================================================================
//  ESCOLHA DO MELHOR CANIDATO
// ===================================================================
Candidato EscolherCandidato(){
   if(g_CandIdx>-1) return g_CandCand; // cache do ciclo anterior reaproveitado se ainda valido? nao: regenera sempre
   vector<Candidato> c=CopyCands(); // copia gerada
   InsertionDesc(c);
   Candidato best;
   double bestAdj=-1e18, bestDist=1e18;
   for(const Candidato& cc:c){
      if(cc.nota<InpScoreMin) continue;
      if(!GateAprovado(cc)) continue;
      double adj=cc.nota;
      // desempate: alinhado com tendencia ganha bonus
      int pref = (bestLado() == (DirecaoTendencia()==1?BUY:SELL)?2:0);
      adj += pref;
      if(adj>bestAdj || (fabs(adj-bestAdj)<0.01 && MathAbs(cc.dist-bestDist)<0.1)) {
         bestAdj=adj; bestDist=cc.dist; best=cc; }
   }
   if(best.nota<InpScoreMin) return {};
   g_CandCand=best; g_CandIdx=-1;
   return best;
}

double bestLado(){
   // indica qual lado a estrategia prefere no momento (conforme tendencia)
   int td=DirecaoTendencia();
   return td==1?1:-1; // +1=comprador, -1=vendedor
}

bool GateAprovado(const Candidato& cc){
   // exigencias minimas
   if(!ConviccaoVela(cc.barIdx)) return false;
   // quarentena liquidez
   double liq = cc.lado==BUY ? LiqAcimaDou() : LiqAbaixoDou();
   if(liq < InpLiqSafe) return false;
   return true;
}

