void DesenharGrafico(){
   if(!InpDraw) return;
   if(g_CntBars<8) return;
   ChartRedraw();

   // --- niveis Fibo ---
   if((int)g_FibsTmp.size()>=2){
      datetime t0=TimeCurrent(), t1=t0+PerSecond()*30;
      for(int i=0;i<(int)g_FibsTmp.size();i++){
         double y = g_FibsTmp[i];
         if(y<0||y>10000) continue;
         Color c=CorFibo(i);
         DrawHorizontalLine(xScale(0,0,y), y, xScale(0,g_CntBars-1,y), c, 1, STYLE_SOLID|STYLE_DASHED);
         string lbl = FiboStr(i);
         if(MathAbs(i-4)<1 || MathAbs(i-2)<1 || MathAbs(i-1)<1){
            lbl += " ";
         }
         Comment(SbName(), lbl + StringFormat("%.4f",y), 0, 10, c, FONT_STYLE_CENTER, 7);
      }
      // destacar faixa 38.2 - 61.8
      if((int)g_FibsTmp.size()>=5){
         double y38=g_FibsTmp[2], y62=g_FibsTmp[4];
         Color cl = COLOR_LIGHTCYAN;
         DrawRectangle(xScale(0,0,y38), y38, xScale(0,g_CntBars-1,y62), y62, cl, 32);
         Comment(SbName()," FAIXA DE RETRACAO 38%-62%", 0, -5, cl, FONT_STYLE_LEFT, 7);
      }
   }

   // --- Ordens Bloco ---
   for(const ZonaOB& z:g_Zonas){
      Color c = (z.lado==+1)?COLOR_DARKGREEN:COLOR_DARKRED;
      double yMid=(z.base+z.topo)/2;
      if(yMid<0||yMid>10000) continue;
      DrawRectangle(xScale(0,z.base), z.base, xScale(0,g_CntBars-1), z.topo, c, 48);
      string nome = (z.lado==+1?"OB SUPORTE":"OB RESISTENCIA");
      Comment(SbName(), nome + " "+StringFormat("%.2f",z.base), 0, 0, (z.lado==+1?clrDarkGreen:clrDarkRed), 7);
   }

   // --- FGVs ---
   for(const FGVd& fv:g_FGVs){
      if(MathAbs(fv.nivel-g_PrecoAtual)>5*CalcATR(11)) continue;
      double px=xScale(0,fv.barra,fv.nivel);
      if(px<0||px>chart_width()) continue; // cuidado: chart_width nao exposto; confiar em xScale valido
      Color c = (fv.preenchido)?COLOR_GRAY : (fv.lado==+1?COLOR_DARKGREEN:COLOR_DARKRED);
      CPnt p = CreatePoint(SbName(), fv.nivel, px);
      p.Layer=0; p.Size=6; p.Type=CLARK_DIAMOND; p.Display=true; p.Color=c;
      string lab = (fv.preenchido?"(preenchido)":"" ) + "FGV "+StringFormat("%.2f",fv.nivel);
      Comment(SbName(), lab, 0, -8, c, FONT_STYLE_LEFT, 6);
   }

   // --- Pontos de liquidez (altas/baixas recentes) ---
   CPnt* pts=new CPnt[32];
   int np=0;
   for(auto &e:g_Altas){
      if(e.barra<0||e.nivel>g_PrecoAtual+InpLiqSafe*2+1000) continue;
      double px=xScale(0,e.barra,e.nivel);
      if(px<0||px>chart_width()){ np++; continue; }
      CPnt *p=pts[np++];
      p->symln=SbName(); p->y=e.nivel; p->x=px; p->Layer=0; p->Size=6; p->Type=CLARK_DIAMOND;
      p->Color=np<2?COLOR_ORANGE:COLOR_RED; p->Visible=true;
   }
   for(auto &e:g_Baixas){
      if(e.barra<0||e.nivel<g_PrecoAtual-InpLiqSafe*2-1000) continue;
      double px=xScale(0,e.barra,e.nivel);
      if(px<0||px>chart_width()){ np++; continue; }
      CPnt *p=pts[np++];
      p->symln=SbName(); p->y=e.nivel; p->x=px; p->Layer=0; p->Size=6; p->Type=CLARK_DIAMOND;
      p->Color=np<2?COLOR_BLUE:COLOR_GREEN; p->Visible=true;
   }
   DeleteArray(pts);
   ChartRedraw();
}

