Real-time badge update function:

```js
function atualizarBadges() {
  const entradas = document.querySelectorAll('.rm-input');
  entradas.forEach(inp => {
    const val = inp.value.replace(/^[\s]*|[^\s]*\s*$/g, '').trim(); // trim spaces around
    const tem = val.length > 0;
    inp.classList.toggle('has-badge', tem);
    if (!tem){ inp.classList.add('no-badge'); return; }
    inp.classList.remove('no-badge');
    const qtd = contagem(val);
    const numero = document.createElement('span');
    numero.className = 'badge' + (qtd > 0 ? ' count-up' : '');
    numero.textContent = qtd > 9 ? `${Math.floor(qtd/10)}k` : qtd;
    inp.appendChild(numero);
  });
}
```

