contagem function:

```js
function contagem(padrao, texto){
  try{ const rg = new RegExp(escape(padrao),'g'); return (texto.match(rg) || []).length; }
  catch(e){ return 0; }
}
```

Escape:

```js
function escapePadrao(s){
  return s.replace(/[.*+?^${}()|[\]\\]/g, m => '\\' + m);
}
```

Process function:

```js
async function processar(){
  const orig = document.getElementById('textoOrig').value;
  if(typeof orig !== 'string'){ return; }
  if(orig.trim().length===0){ mostrarToast('📩 Cole algum texto para a mágica acontecer 🙂', 'warn'); return; }
  const len = orig.length;
  if(len>200000){ mostrarToast('⚠️ Muito texto! Isso pode levar alguns segundos. Paciência é virtude 😉', 'warn'); return; }
  const resultadoEl = document.getElementById('resultado');
  resultadoEl.value='';
  let texto = orig;
  const etapas = [];
  let habilitado = true;
  const btn = document.getElementById('btnLimpar');
  btn.disabled = true;
  btn.textContent = '🔍 Processando…';
  btn.style.opacity='.65';
  try {
    for(let i=0;i<etapasDefinidas.length;i++){
      const card = document.querySelector(`.card-etapa[data-id="${i+1}"]`);
      const padrao = card.querySelector('.rm-input').value.trim();
      if(padrao.length===0){ continue; }
      const antes = texto;
      const rg = new RegExp(escapePadrao(padrao),'g');
      texto = texto.replace(rg,'');
      const n = antes !== texto ? (antes.match(rg)||[]).length : 0;
      etapas.push({ indice:i+1, padrao, removidos:n, card });
      // destaque na etapa
      card.querySelector('.etapa-status').textContent = `✅ ${n}× tirados`;
      card.style.borderColor = '#3fb950';
      setTimeout(()=>{ card.style.borderColor='var(--limite-borda)'; }, 1200);
      atualizarBadges();
      atualizarContagemEtapa(card);
    }
    resultadoEl.value = texto;
    resultadoEl.focus();
    const tot = etapas.reduce((a,e)=>a+e.removidos,0);
    mostrarToast(`✅ Sucesso! Removeu ${tot} ocorrência(s) no total. Dê uma olhada abaixo 👇`, 'good');
    // foco no botão copiar
    setTimeout(()=> document.getElementById('btnCopiar').focus(), 400);
  } catch(err){
    mostrarToast('⚠️ Deu ruim ao processar o texto. Confira os padrões digitados.', 'warn');
  } finally{
    btn.disabled=false;
    btn.textContent='🧹 Limpar de novo';
    btn.style.opacity=1;
    btn.setAttribute('aria-busy','false');
  }
}
```

