  let mi = Math.floor(n/1000000);
  let r = n%1000000;
  let f = r ? r/1000000 : 0;
  let combinado = mi + f;
  let s = combinado.toFixed(2);
  if(s.endsWith('00')) s = s.slice(0,-2); else if(s.endsWith('0')) s = s.slice(0,-1);
  s = s.replace(/\./g,',');
  return s + ' mi';
}
