JS notification builder:

```js
function avisar(msg, tipo){
  tipo = tipo||'info';
  const el = document.createElement('div');
  const ic = { info:'ℹ️', sucesso:'✅', alerta:'⚠️', erro:'❌' }[tipo];
  const cls = 'notif'+({info:'',sucesso:'',alerta:'',erro:''}[tipo]); // maps tipo → class suffix
  // simpler: build classes directly
  el.className = `notif ${tipo==='sucesso'?'sucesso':''}${tipo==='erro'?' erro':''}`;
  el.innerHTML = `<span class="ico">${ic}</span>${escHTML(msg)}`;
  const container = document.querySelector('.bar-notif');
  if(container){
    container.style.pointerEvents='none';
    if(container.childElementCount > 3) container.removeChild(container.firstChild);
    container.style.pointerEvents='auto';
    container.appendChild(el);
    clearTimeout(el._tm);
    el._tm = setTimeout(()=>{ el.classList.add('saindo');
      el.addEventListener('transitionend',()=>{ el.remove(); }, {once:true}); }, 3600);
  }
}
```
Class mapping: tipos → suffixes: success→'sucesso', error→'erro', alert→none extra. So `notif${tipo==='sucesso'?'sucesso':''}${tipo==='erro'?' erro':''}` gives notif, notif-sucesso, notif-erro. ✓.

