```js
async function executar(){
  if(!podereiRodar()){
    avisar('📩 Cole algum texto no campo grande no topo para começar 😉', 'info'); return;
  }
  const tamanho = ENTRADA.value.length;
  if(tamanho > 350000){
    avisar('⚠️ Esse texto é gigante (mais de 350 mil caracteres)! Vai levar alguns segundos 😉', 'alerta'); return;
  }
  const inicio = performance.now();
  let conteudo = ENTRADA.value;
  const historico = [];
  BOTAO_LIMPAR.disabled = true;
  BOTAO_RESET.disabled = true;
  BOTAO_COPY.disabled = true;
  mostrarCarregador();

  try {
    for(let idx=0;idx<PASSOS.length;idx++){
      const carta = CARTOES[idx];
      const alvo = BADGES[idx]?.value;
      const padrao = String(alvo||'').trimStart().trimEnd();
      if(padrao.length<=0){
        atualizarCarta(carta, '-', 0);
        continue;
      }
      const ante = conteudo;
      const reg = new RegExp(escaparPadrao(padrao),'g');
      const achadas = ante.match(reg)?.length||0;
      conteudo = conteudo.replace(reg, '');
      const duracao = performance.now()-inicio;
      historico.push({idx:idx+1,padrao,palpites:achadas,tempo:Math.round(duracao)});
      atualizarCarta(carta, padrao, achadas);
      desenharIndicadores();
      if(idx<PASSOS.length-1) await new Promise(r=>setTimeout(r,170));
    }
    const total = historico.reduce((a,h)=>a+h.palpites,0);
    const finalizado = performance.now()-inicio;
    RESULTADO.value = conteudo;
    RESULTADO.focus();
    placares(total, finalizado);
    avisar(`✅ Sucesso! Eliminei ${total.toLocaleString()} ocorrência(s) em ${(finalizado/1000).toFixed(1)} segundos. Veja o resultado abaixo 👇`, 'sucesso');
    setTimeout(()=>BOTAO_COPY.focus(), 380);
  }catch(err){
    BOTAO_LIMPAR.disabled=false;
    BOTAO_RESET.disabled=false;
    BOTAO_COPY.disabled=false;
    ocultoCarregador();
    const msg = err instanceof Error ? err.message : 'Algo saiu errado durante a operação 😉';
    avisar('⚠️ Não conseguiu remover tudo. Confira os padrões digitados nas caixinhas e tente novamente.', 'erro');
  }
}
function atualizarCarta(carta, padrao, qtd){
  const linha = carta.querySelector('.status-linha');
  if(!linha) return;
  const txt = qtd>0 ? `✅ ${qtd}× apagado(a) "${escHtml(padrao)}"` : '— nenhuma ocorrência aqui';
  linha.className = 'status-linha '+ (qtd>0?'apagado':'');
  linha.textContent = txt;
  carta.style.borderColor = qtd>0 ? '#3fb950' : 'var(--limite-borda)';
}
function placares(total, dur){
  const cabeca = documento.querySelector('.cabeça-res');
  if(!cabeca) return;
  const st = cabeca.querySelector('.resumo-stats');
  if(!st){
    st = document.createElement('div'); st.className='resumo-stats';
    cabeca.appendChild(st);
  }
  const item = document.createElement('span');
  item.className='stat';
  item.innerHTML = `<span class="dot"></span><span>Fiz ${total.toLocaleString()} ajustes</span>`;
  if(dur>0){
    const it2 = document.createElement('span'); it2.className='stat';
    it2.innerHTML = `<span class="dot" style="background:#7b5ffa"></span><span>Pronto em ${dur.toFixed(1)}s</span>`;
    st.appendChild(it2);
  }
}
